// Show verified children's headlines generated by the scheduled GitHub action.
(function(){
let data=null,requested=false;
async function load(){try{const r=await fetch('daily-kids-news.json?ts='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error(r.status);const j=await r.json();if(Array.isArray(j.items)&&j.items.length)data=j;}catch(e){console.warn('Kindernachrichten nicht verfügbar',e)}finally{requested=false;show()}}
function show(){
 const box=document.querySelector('.laWorldNews');if(!box||!data||box.dataset.autoNews===data.updated)return;
 const p=box.querySelector('p.mini');if(!p||!p.textContent.includes('Weltnachricht'))return;
 p.remove();const wrap=document.createElement('div');wrap.className='laTodayItems';
 const head=document.createElement('p');head.className='mini';head.textContent='Aktuelle Kindernachrichten · ZDF logo! · Stand '+data.updated;wrap.append(head);
 for(const item of data.items.slice(0,3)){if(!/^https:\/\/www\.logo\.de\//.test(item.url))continue;const el=document.createElement('div');el.className='laTodayItem';const a=document.createElement('a');a.href=item.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=item.title;el.append(a);wrap.append(el)}
 box.append(wrap);box.dataset.autoNews=data.updated;
}
new MutationObserver(()=>{show();if(!data&&!requested){requested=true;load()}}).observe(document.getElementById('app')||document.body,{childList:true,subtree:true});
})();
